// Generate a poster and render it in the iframe.
try {
  const out = await anna.image.generate({
    prompt: "A bold art-deco poster of the planet Mars.",
    n: 1,
    size: "1024x1024",
  });
  posterImg.src = out.images[0].url;        // ~30 min TTL
  quotaLabel.textContent = `${out.quota_used.images_today}/${out.quota_used.images_quota}`;
} catch (e) {
  switch (e.code) {
    case "APP_NOT_GRANTED":     setStatus("Enable image generation in Anna Admin."); break;
    case "APP_QUOTA_EXCEEDED":  setStatus("Daily image quota hit — try again tomorrow."); break;
    case "APP_INVALID_REQUEST": setStatus(`Bad request: ${e.message}`); break;
    case "APP_PROVIDER_ERROR":  setStatus("Upstream provider hiccup — retry once."); break;
    default: throw e;
  }
}

// Restyle a previously-generated poster.
const gen  = await anna.image.generate({ prompt: "art-deco Mars poster", n: 1 });
const edit = await anna.image.edit({
  image_url: gen.images[0].url,           // re-use immediately — URL is fresh
  prompt: "Restyle this poster in a cyberpunk aesthetic with neon magenta.",
  n: 1,
});
outImg.src = edit.images[0].url;
